          ]
        },
        {
          "proposicao": "O texto indica expectativa de aumento de confiabilidade, racionalização de custos e apoio à manutenção com base padronizada e base de dados integrada de relatórios preditivos dos bancos de baterias.",
          "trechos": [
            "E0bcb5b390f3d64f5:0:700",
